+    "cpsid i\n" "tst lr,#4\n" "ite eq\n" "mrseq r0,msp\n" "mrsne r0,psp\n" \
+    "mov r1,lr\n" "movs r2,#" #kind "\n" \
+    "ldr r3,=comp_v11_journal_fault_stack+128\n" "msr msp,r3\n" "b comp_v11_journal_fault\n");}
